<?php require dirname(__DIR__).'/config/config.php'; require dirname(__DIR__).'/vendor/autoload.php'; use App\Helpers\Security; use App\Helpers\Audit; $u=Security::requireRole(['administrador','gerente','operador']); $clientes=db()->query('SELECT id,nome FROM clientes ORDER BY nome')->fetchAll();$cacambas=db()->query("SELECT id,numero,tipo FROM cacambas WHERE status='disponivel' ORDER BY numero")->fetchAll();$motoristas=db()->query("SELECT id,nome FROM motoristas WHERE status=1 ORDER BY nome")->fetchAll();$msg=null;if($_SERVER['REQUEST_METHOD']==='POST'){Security::checkCsrf($_POST['csrf']??null);$s=db()->prepare('INSERT INTO pedidos(cliente_id,cacamba_id,motorista_id,data_entrega,data_retirada_prevista,endereco_entrega,valor,forma_pagamento,status,observacao) VALUES(?,?,?,?,?,?,?,?,?,?)');$s->execute([(int)$_POST['cliente_id'],$_POST['cacamba_id']?:null,$_POST['motorista_id']?:null,$_POST['data_entrega']?:null,$_POST['data_retirada_prevista']?:null,trim($_POST['endereco_entrega']),max(0,(float)$_POST['valor']),trim($_POST['forma_pagamento']),$_POST['status'],trim($_POST['observacao']??'')]);$id=(int)db()->lastInsertId();if($_POST['status']==='entregue' && $_POST['cacamba_id']){db()->prepare("UPDATE cacambas SET status='em_uso' WHERE id=?")->execute([(int)$_POST['cacamba_id']]);}Audit::log('Cadastro de pedido','pedidos',$id);$msg='Pedido cadastrado.';}$rows=db()->query('SELECT p.*,c.nome cliente,ca.numero cacamba FROM pedidos p JOIN clientes c ON c.id=p.cliente_id LEFT JOIN cacambas ca ON ca.id=p.cacamba_id ORDER BY p.id DESC LIMIT 100')->fetchAll();?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pedidos</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="css/app.css"></head><body><div class="container py-4"><h1>Pedidos / Aluguéis</h1><a href="dashboard.php">← Dashboard</a><?php if($msg):?><div class="alert alert-success mt-3"><?=Security::e($msg)?></div><?php endif;?><div class="card p-3 my-4"><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=Security::csrf()?>"><div class="col-md-3"><select name="cliente_id" class="form-select" required><option value="">Cliente</option><?php foreach($clientes as $c):?><option value="<?=$c['id']?>"><?=Security::e($c['nome'])?></option><?php endforeach;?></select></div><div class="col-md-2"><select name="cacamba_id" class="form-select"><option value="">Caçamba</option><?php foreach($cacambas as $c):?><option value="<?=$c['id']?>"><?=Security::e($c['numero'])?> (<?=Security::e($c['tipo'])?>)</option><?php endforeach;?></select></div><div class="col-md-2"><select name="motorista_id" class="form-select"><option value="">Motorista</option><?php foreach($motoristas as $m):?><option value="<?=$m['id']?>"><?=Security::e($m['nome'])?></option><?php endforeach;?></select></div><div class="col-md-2"><input class="form-control" type="datetime-local" name="data_entrega"></div><div class="col-md-2"><input class="form-control" type="datetime-local" name="data_retirada_prevista"></div><div class="col-md-3"><input class="form-control" name="endereco_entrega" placeholder="Endereço de entrega" required></div><div class="col-md-2"><input class="form-control" name="valor" type="number" step="0.01" placeholder="Valor" required></div><div class="col-md-2"><input class="form-control" name="forma_pagamento" placeholder="Pagamento"></div><div class="col-md-2"><select class="form-select" name="status"><option>orcamento</option><option>confirmado</option><option>entregue</option><option>retirado</option><option>cancelado</option></select></div><div class="col-md-2"><button class="btn btn-primary w-100">Salvar pedido</button></div></form></div><div class="table-responsive"><table class="table"><thead><tr><th>#</th><th>Cliente</th><th>Caçamba</th><th>Entrega</th><th>Status</th><th>Valor</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=Security::e($r['cliente'])?></td><td><?=Security::e($r['cacamba']??'-')?></td><td><?=Security::e($r['data_entrega']??'-')?></td><td><?=Security::e($r['status'])?></td><td>R$ <?=number_format((float)$r['valor'],2,',','.')?></td></tr><?php endforeach;?></tbody></table></div></div></body></html>
